<?php
namespace AutoDealership\Reports;

use AutoDealership\Audit\AuditLog;
use AutoDealership\Core\CurrencySettings;
use AutoDealership\Database\Schema;
use AutoDealership\Marketing\AffiliateCommissionService;
use AutoDealership\Pricing\Money;
use AutoDealership\Security\BranchScope;

defined( 'ABSPATH' ) || exit;

/** Branch-scoped, timezone-aware affiliate commission reports. */
final class AffiliateCommissionReport {
	public static function report( array $filters = array() ) {
		global $wpdb;
		if ( ! self::can_manage() ) { return new \WP_Error( 'adc_affiliate_report_forbidden', 'Affiliate commission report permission is required.', array( 'status'=>403 ) ); }
		$normalized = self::normalize( $filters ); if ( is_wp_error( $normalized ) ) { return $normalized; }
		$args = array(); $where = self::where( $normalized, $args, 'c' ); $commissions = Schema::table( 'affiliate_commissions' ); $entries = Schema::table( 'affiliate_commission_entries' );
		$currencies = $wpdb->get_col( $wpdb->prepare( "SELECT DISTINCT c.currency_code FROM $commissions c WHERE $where", $args ) );
		if ( $wpdb->last_error ) { return self::error( 'adc_affiliate_report_query' ); }
		$currency = CurrencySettings::base_code();
		if ( '' === $currency ) { return new \WP_Error( 'adc_currency_required', 'Configure the system base currency before running financial reports.', array( 'status'=>409 ) ); }
		if ( count( $currencies ) > 1 || ( $currencies && $currency !== strtoupper( (string) $currencies[0] ) ) ) { return new \WP_Error( 'adc_affiliate_report_currency_mixed', 'The selected report contains unsupported or mixed currencies and cannot be presented in the configured base currency.', array( 'status'=>409 ) ); }
		$stats = $wpdb->get_row( $wpdb->prepare( "SELECT COUNT(*) commission_count,COALESCE(SUM(c.amount),0) gross,COALESCE(SUM(CASE WHEN c.status='pending_review' THEN c.amount ELSE 0 END),0) pending_review,COALESCE(SUM(CASE WHEN c.status='approved' THEN c.amount ELSE 0 END),0) approved,COALESCE(SUM(CASE WHEN c.status='paid' THEN c.amount ELSE 0 END),0) paid,COALESCE(SUM(CASE WHEN c.status='void' THEN c.amount ELSE 0 END),0) voided,COALESCE(SUM(CASE WHEN c.status='paid_sale_returned' THEN c.amount ELSE 0 END),0) returned FROM $commissions c WHERE $where", $args ), ARRAY_A );
		if ( $wpdb->last_error || ! $stats ) { return self::error( 'adc_affiliate_report_query' ); }
		$entry_args = array(); $entry_where = self::where( $normalized, $entry_args, 'c' ); $ledger = $wpdb->get_row( $wpdb->prepare( "SELECT COALESCE(SUM(e.amount),0) net_ledger,COALESCE(SUM(CASE WHEN e.amount<0 THEN -e.amount ELSE 0 END),0) reversals FROM $entries e INNER JOIN $commissions c ON c.id=e.commission_id WHERE $entry_where", $entry_args ), ARRAY_A );
		if ( $wpdb->last_error || ! $ledger ) { return self::error( 'adc_affiliate_report_query' ); }
		$summary = array( 'currency'=>$currency, 'commission_count'=>(int) $stats['commission_count'], 'gross'=>(int) $stats['gross'], 'pending_review'=>(int) $stats['pending_review'], 'approved'=>(int) $stats['approved'], 'paid'=>(int) $stats['paid'], 'voided'=>(int) $stats['voided'], 'returned'=>(int) $stats['returned'], 'net_ledger'=>(int) $ledger['net_ledger'], 'reversals'=>(int) $ledger['reversals'] ); self::money_fields( $summary );
		$by_affiliate = self::grouped( $normalized, 'affiliate_user_id', 'u.display_name', $commissions, $entries ); $by_branch = self::grouped( $normalized, 'branch_id', "CONCAT('Branch #',c.branch_id)", $commissions, $entries ); $by_period = self::periods( $normalized, $commissions, $entries ); $reconciliation = self::reconciliation( $normalized );
		if ( is_wp_error( $by_affiliate ) || is_wp_error( $by_branch ) || is_wp_error( $by_period ) || is_wp_error( $reconciliation ) ) { return self::error( 'adc_affiliate_report_query' ); }
		return array( 'filters'=>$normalized, 'summary'=>$summary, 'by_affiliate'=>$by_affiliate, 'by_branch'=>$by_branch, 'by_period'=>$by_period, 'reconciliation'=>$reconciliation );
	}

	public static function export( array $filters = array(), string $format = 'csv' ) {
		$result = self::report( $filters ); if ( is_wp_error( $result ) ) { return $result; } $rows = array();
		foreach ( array( 'affiliate'=>'by_affiliate', 'branch'=>'by_branch', 'period'=>'by_period' ) as $type=>$key ) { foreach ( $result[ $key ] as $row ) { $rows[] = array( 'group_type'=>$type, 'group_id'=>(int) ( $row['group_id'] ?? 0 ), 'group_label'=>(string) ( $row['group_label'] ?? $row['period'] ?? '' ), 'period'=>(string) ( $row['period'] ?? '' ), 'commission_count'=>(int) $row['commission_count'], 'gross'=>(int) $row['gross'], 'reversals'=>(int) $row['reversals'], 'net_ledger'=>(int) $row['net_ledger'], 'pending_review'=>(int) $row['pending_review'], 'approved'=>(int) $row['approved'], 'paid'=>(int) $row['paid'], 'voided'=>(int) $row['voided'], 'returned'=>(int) $row['returned'] ); } }
		$format = in_array( $format, array( 'csv', 'excel', 'pdf' ), true ) ? $format : 'csv';
		if ( ! AuditLog::record( 'affiliate_commission.report_exported', 'affiliate_commission_report', 0, 'Affiliate commission ' . strtoupper( $format ) . ' export', null, array( 'from'=>$result['filters']['from'], 'to'=>$result['filters']['to'], 'timezone'=>$result['filters']['timezone'], 'currency'=>CurrencySettings::base_code(), 'format'=>$format, 'row_count'=>count( $rows ) ) ) ) { return new \WP_Error( 'adc_affiliate_report_audit', 'The affiliate report could not be audited.', array( 'status'=>500 ) ); }
		return array( 'csv'=>self::csv( $rows, $result['filters'] ), 'data'=>$rows, 'rows'=>count( $rows ), 'filters'=>$result['filters'] );
	}

	private static function grouped( array $filters, string $group_field, string $label_sql, string $commissions, string $entries ) {
		global $wpdb; $args = array(); $where = self::where( $filters, $args, 'c' ); $rows = $wpdb->get_results( $wpdb->prepare( "SELECT c.$group_field group_id,$label_sql group_label,COUNT(*) commission_count,COALESCE(SUM(c.amount),0) gross,COALESCE(SUM(CASE WHEN c.status='pending_review' THEN c.amount ELSE 0 END),0) pending_review,COALESCE(SUM(CASE WHEN c.status='approved' THEN c.amount ELSE 0 END),0) approved,COALESCE(SUM(CASE WHEN c.status='paid' THEN c.amount ELSE 0 END),0) paid,COALESCE(SUM(CASE WHEN c.status='void' THEN c.amount ELSE 0 END),0) voided,COALESCE(SUM(CASE WHEN c.status='paid_sale_returned' THEN c.amount ELSE 0 END),0) returned FROM $commissions c LEFT JOIN {$wpdb->users} u ON u.ID=c.affiliate_user_id WHERE $where GROUP BY c.$group_field ORDER BY gross DESC,group_id ASC", $args ), ARRAY_A );
		if ( $wpdb->last_error ) { return new \WP_Error( 'adc_affiliate_report_query' ); } $ledger_args = array(); $ledger_where = self::where( $filters, $ledger_args, 'c' ); $ledger_rows = $wpdb->get_results( $wpdb->prepare( "SELECT c.$group_field group_id,COALESCE(SUM(e.amount),0) net_ledger,COALESCE(SUM(CASE WHEN e.amount<0 THEN -e.amount ELSE 0 END),0) reversals FROM $entries e INNER JOIN $commissions c ON c.id=e.commission_id WHERE $ledger_where GROUP BY c.$group_field", $ledger_args ), ARRAY_A ); if ( $wpdb->last_error ) { return new \WP_Error( 'adc_affiliate_report_query' ); }
		$ledger=array(); foreach($ledger_rows as $row){$ledger[(int)$row['group_id']]=array('net_ledger'=>(int)$row['net_ledger'],'reversals'=>(int)$row['reversals']);} foreach($rows as &$row){$values=$ledger[(int)$row['group_id']]??array('net_ledger'=>0,'reversals'=>0);$row['net_ledger']=$values['net_ledger'];$row['reversals']=$values['reversals'];self::money_fields($row);}unset($row);return $rows?:array();
	}

	private static function periods( array $filters, string $commissions, string $entries ) {
		global $wpdb; $args=array(); $where=self::where($filters,$args,'c'); $rows=$wpdb->get_results($wpdb->prepare("SELECT c.created_at,c.amount,c.status,COALESCE((SELECT SUM(e.amount) FROM $entries e WHERE e.commission_id=c.id),0) net_ledger FROM $commissions c WHERE $where ORDER BY c.created_at ASC",$args),ARRAY_A); if($wpdb->last_error){return new \WP_Error('adc_affiliate_report_query');}
		$groups=array();$tz=new \DateTimeZone($filters['timezone']);foreach($rows as $row){$date=(new \DateTimeImmutable((string)$row['created_at'],new \DateTimeZone('UTC')))->setTimezone($tz);$period='day'===$filters['period']?$date->format('Y-m-d'):$date->format('Y-m');if(!isset($groups[$period])){$groups[$period]=array('group_id'=>0,'group_label'=>$period,'period'=>$period,'commission_count'=>0,'gross'=>0,'reversals'=>0,'net_ledger'=>0,'pending_review'=>0,'approved'=>0,'paid'=>0,'voided'=>0,'returned'=>0);}++$groups[$period]['commission_count'];$groups[$period]['gross']+=(int)$row['amount'];$groups[$period]['net_ledger']+=(int)$row['net_ledger'];if((int)$row['net_ledger']<0){$groups[$period]['reversals']+=abs((int)$row['net_ledger']);}$key=(string)$row['status'];if(isset($groups[$period][$key])){$groups[$period][$key]+=(int)$row['amount'];}}foreach($groups as &$row){self::money_fields($row);}unset($row);return array_values($groups);
	}

	private static function reconciliation( array $filters ) {
		global $wpdb; $currency=CurrencySettings::base_code(); $commissions=Schema::table('affiliate_commissions');$entries=Schema::table('affiliate_commission_entries');$issues=Schema::table('affiliate_commission_migration_issues');$args=array();$where=self::where($filters,$args,'c');$items=array();$missing=$wpdb->get_results($wpdb->prepare("SELECT c.id,'commission_without_ledger' issue_type,'Commission has no ledger entry.' reason FROM $commissions c LEFT JOIN $entries e ON e.commission_id=c.id WHERE $where GROUP BY c.id HAVING COUNT(e.id)=0 LIMIT 100",$args),ARRAY_A);$invalid_args=array_merge($args,array($currency));$invalid=$wpdb->get_results($wpdb->prepare("SELECT c.id,'invalid_commission' issue_type,'Commission has an invalid state, amount, or currency.' reason FROM $commissions c WHERE $where AND (c.currency_code<>%s OR c.status NOT IN ('pending_review','approved','paid','void','paid_sale_returned') OR c.amount<0) LIMIT 100",$invalid_args),ARRAY_A);foreach(array_merge($missing?:array(),$invalid?:array()) as $item){$items[]=$item;}$issue_args=array();$issue_where=self::where($filters,$issue_args,'c');$migration=$wpdb->get_results($wpdb->prepare("SELECT i.commission_id id,CONCAT('migration_',i.issue_type) issue_type,i.reason FROM $issues i INNER JOIN $commissions c ON c.id=i.commission_id WHERE i.status='open' AND $issue_where ORDER BY i.id DESC LIMIT 100",$issue_args),ARRAY_A);foreach($migration?:array() as $item){$items[]=$item;}$orphan_args=array();list($orphan_scope,$orphan_scope_args)=BranchScope::predicate('e.branch_id');$orphan_args=array_merge($orphan_args,$orphan_scope_args);$orphan_sql="SELECT e.commission_id id,'orphan_ledger_entry' issue_type,'Ledger entry has no commission record.' reason FROM $entries e LEFT JOIN $commissions c ON c.id=e.commission_id WHERE c.id IS NULL AND $orphan_scope LIMIT 100";$orphan=$wpdb->get_results($orphan_args?$wpdb->prepare($orphan_sql,$orphan_args):$orphan_sql,ARRAY_A);foreach($orphan?:array() as $item){$items[]=$item;}return array('summary'=>array('total'=>count($items),'commission_without_ledger'=>count($missing?:array()),'invalid_commission'=>count($invalid?:array()),'migration_issues'=>count($migration?:array()),'orphan_ledger_entries'=>count($orphan?:array())),'items'=>$items);
	}

	private static function normalize( array $filters ) { $range=ReportDateRange::normalize($filters);if(is_wp_error($range)){return $range;}$status=sanitize_key((string)($filters['status']??''));if(''!==$status&&!in_array($status,AffiliateCommissionService::statuses(),true)){return new \WP_Error('adc_affiliate_report_status','Invalid commission status.',array('status'=>400));}$period=sanitize_key((string)($filters['period']??'month'));if(!in_array($period,array('day','month'),true)){return new \WP_Error('adc_affiliate_report_period','Invalid report period.',array('status'=>400));}return array_merge($range,array('status'=>$status,'period'=>$period,'affiliate_user_id'=>absint($filters['affiliate_user_id']??0),'branch_id'=>absint($filters['branch_id']??0))); }
	private static function where(array $filters,array &$args,string $alias):string{$where=array("$alias.created_at >= %s","$alias.created_at < %s");$args[]=$filters['from_utc'];$args[]=$filters['to_utc'];if(''!==$filters['status']){$where[]="$alias.status=%s";$args[]=$filters['status'];}if($filters['affiliate_user_id']>0){$where[]="$alias.affiliate_user_id=%d";$args[]=$filters['affiliate_user_id'];}if($filters['branch_id']>0){$where[]="$alias.branch_id=%d";$args[]=$filters['branch_id'];}list($scope,$scope_args)=BranchScope::predicate("$alias.branch_id");$where[]=$scope;$args=array_merge($args,$scope_args);return implode(' AND ',$where);}
	private static function money_fields(array &$row):void{foreach(array('gross','pending_review','approved','paid','voided','returned','net_ledger','reversals') as $field){$row[$field.'_amount']=Money::decimal((int)($row[$field]??0));}}
	private static function csv(array $rows,array $filters):string{$stream=fopen('php://temp','w+');fwrite($stream,"\xEF\xBB\xBF");fputcsv($stream,array('report_from','report_to','timezone','currency','group_type','group_id','group_label','period','commission_count','gross_amount','reversals_amount','net_ledger_amount','pending_review_amount','approved_amount','paid_amount','voided_amount','returned_amount'));foreach($rows as $row){fputcsv($stream,array($filters['from'],$filters['to'],$filters['timezone'],CurrencySettings::base_code(),self::safe_cell($row['group_type']),self::safe_cell($row['group_id']),self::safe_cell($row['group_label']),self::safe_cell($row['period']),$row['commission_count'],Money::decimal((int)$row['gross']),Money::decimal((int)$row['reversals']),Money::decimal((int)$row['net_ledger']),Money::decimal((int)$row['pending_review']),Money::decimal((int)$row['approved']),Money::decimal((int)$row['paid']),Money::decimal((int)$row['voided']),Money::decimal((int)$row['returned']))); }rewind($stream);$csv=stream_get_contents($stream);fclose($stream);return(string)$csv;}
	private static function safe_cell($value):string{$value=(string)$value;return preg_match('/^[=+\-@\t\r]/',$value)?"'".$value:$value;}
	private static function can_manage():bool{return current_user_can('adc_manage_affiliate_commissions')||current_user_can('manage_options');}
	private static function error(string $code):\WP_Error{return new \WP_Error($code,'Unable to load the affiliate commission report.',array('status'=>500));}
}
